import ast

def safe_eval(expr, allowed_names):
    node = ast.parse(expr, mode='eval').body

    def _eval(n):
        if isinstance(n, ast.Constant):
            return n.value
        elif isinstance(n, ast.Name):
            if n.id in allowed_names:
                return allowed_names[n.id]
            raise ValueError(f"Invalid name: {n.id}")
        elif isinstance(n, ast.Compare):
            left = _eval(n.left)
            for op, comparator in zip(n.ops, n.comparators):
                right = _eval(comparator)
                if isinstance(op, ast.Eq):
                    if not (left == right): return False
                elif isinstance(op, ast.NotEq):
                    if not (left != right): return False
                elif isinstance(op, ast.Lt):
                    if not (left < right): return False
                elif isinstance(op, ast.LtE):
                    if not (left <= right): return False
                elif isinstance(op, ast.Gt):
                    if not (left > right): return False
                elif isinstance(op, ast.GtE):
                    if not (left >= right): return False
                else:
                    raise ValueError(f"Unsupported op: {op}")
                left = right
            return True
        elif isinstance(n, ast.BoolOp):
            if isinstance(n.op, ast.And):
                for val in n.values:
                    if not _eval(val): return False
                return True
            elif isinstance(n.op, ast.Or):
                for val in n.values:
                    if _eval(val): return True
                return False
        elif isinstance(n, ast.UnaryOp):
            if isinstance(n.op, ast.Not):
                return not _eval(n.operand)
        raise ValueError(f"Unsupported node: {type(n)}")

    return _eval(node)

