# Check if all names are allowed
def check_names(node, allowed_fields):
    for n in ast.walk(node):
        if isinstance(n, ast.Name):
            if n.id not in allowed_fields:
                raise ValueError(f"Invalid field: {n.id}")

def safe_eval(node, allowed_names):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        return allowed_names[node.id]
    elif isinstance(node, ast.Compare):
        left = safe_eval(node.left, allowed_names)
        for op, comparator in zip(node.ops, node.comparators):
            right = safe_eval(comparator, allowed_names)
            if isinstance(op, ast.Eq):
                res = (left == right)
            elif isinstance(op, ast.NotEq):
                res = (left != right)
            elif isinstance(op, ast.Lt):
                res = (left < right)
            elif isinstance(op, ast.LtE):
                res = (left <= right)
            elif isinstance(op, ast.Gt):
                res = (left > right)
            elif isinstance(op, ast.GtE):
                res = (left >= right)
            else:
                raise ValueError(f"Unsupported op: {op}")
            if not res:
                return False
            left = right
        return True
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            for val in node.values:
                if not safe_eval(val, allowed_names): return False
            return True
        elif isinstance(node.op, ast.Or):
            for val in node.values:
                if safe_eval(val, allowed_names): return True
            return False
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not safe_eval(node.operand, allowed_names)
    raise ValueError(f"Unsupported node: {type(node)}")

def filter_users(expr, users):
    try:
        node = ast.parse(expr, mode='eval').body
        check_names(node, {"id", "name", "email"})
        return [u for u in users if safe_eval(node, u)]
    except Exception as e:
        return None

